#!/bin/zsh
# Round 2, learned-model retest (X060): decisions and the analysis record. DEV = seeds 1001-1004, both orders, 17 sequences.
cd ~/SamsungPRISM_FiveBlindSeconds/opt
D() { ../.venv/bin/python harness/fbsopt.py decide "$1" --status "$2" --reason "$3" > /dev/null; echo "$1 -> $2"; }
D DEV0-dev-identity-J validation "136/136 DEV outputs byte-identical to the champion (snapshot J = I + edits_12, all flags at defaults)"
D X060a-velaid-loeo-s1 rejected "Held-out learned velocity rows (sigma x1) are harmful: DEV composite +53.7 % [+38.1, +73.4] vs X108b (EuRoC +34.6 %, TUM-VI +264 %); the network is over-confident (held-out 3-D RMSE 0.58-0.98 m/s vs predicted 3-D sigma 0.23-0.46)"
D X060b-velaid-loeo-s2 rejected "Held-out learned velocity rows (sigma x2): DEV composite +26.4 % [+15.3, +40.1] vs X108b - harmful"
D X060e-velaid-loeo-s4 rejected "Held-out learned velocity rows (sigma x4): DEV composite +9.0 % [+3.6, +15.9] vs X108b - harmful"
D X060f-velaid-loeo-s8 rejected "Held-out learned velocity rows (sigma x8): DEV composite +2.6 % [-0.8, +5.9], EuRoC +0.2 %, TUM-VI +29.6 % - no scale helps; the effect only vanishes as the aid is switched off. Also inadmissible as shipped code (PyTorch, side files) and +55 % runtime"
D X060c-velaid-inpool-s1 rejected "THREAT MEASUREMENT ONLY (in-pool = test missions in training = memorisation, never admissible): sigma x1 DEV composite +5.1 % [-4.2, +17.7]"
D X060d-velaid-inpool-s2 rejected "THREAT MEASUREMENT ONLY (memorisation, never admissible): sigma x2 DEV composite -7.9 % [-12.9, -1.6]"
D X060g-velaid-inpool-s4 rejected "THREAT MEASUREMENT ONLY (memorisation, never admissible): sigma x4 DEV composite -9.3 % [-13.4, -6.0] (EuRoC -8.2 %, TUM-VI -20.9 %) - the bound of the memorisation threat for this model class"
D X060h-velaid-inpool-s8 rejected "THREAT MEASUREMENT ONLY (memorisation, never admissible): sigma x8 DEV composite -5.0 % [-7.8, -3.1]"
P="../.venv/bin/python harness/fbsopt.py analysis"
eval $P AN13-learned-retest --title "'Learned-model threat, retested under held-out evaluation'" --status done \
  --question "'Does a compact learned velocity model help when the test environment was never seen in training, and how much could memorising the public sequences gain?'" \
  --method "'1-D CNN (4 conv layers, about 73 k weights) on 1 s windows at 100 Hz (6 channels: gyro and accelerometer as recorded, gaps filled) plus the gravity direction in the body frame from the X108b attitude, body-frame velocity target from ground truth, heteroscedastic Gaussian NLL, AdamW + one-cycle, 14 epochs, trained on TRAIN missions (seeds 5001-5004) and tested on DEV missions (seeds 1001-1004); folds: leave-one-environment-out for EuRoC (MH, V1, V2) and leave-one-room-out for TUM-VI (room1-6); predictions fused into X108b as world-frame velocity rows with the predicted variance x s^2 (s = 1, 2, 4, 8) wherever no zero-velocity row exists; DEV (136 missions) vs X108b, paired bootstrap over sequences. In-pool folds (trained on the test missions) measure memorisation only.'" \
  --result "'Held-out velocity RMSE (m/s), net / estimator / zero: MH 0.81/0.32/0.92, V1 0.58/0.23/0.80, V2 0.61/0.27/0.70, rooms 0.67-0.98/0.10-0.18/0.56-1.13 (worse than zero in room4 and room6); predicted 3-D sigma 0.23-0.46 (over-confident: 3-D RMS error / sigma = 1.3-3.2). Fusion, held-out: s1 +53.7 %, s2 +26.4 %, s4 +9.0 % [+3.6, +15.9], s8 +2.6 % [-0.8, +5.9] composite (always worse; TUM-VI +30 to +264 %). In-pool: s1 +5.1 %, s2 -7.9 %, s4 -9.3 % [-13.4, -6.0] (EuRoC -8.2 %, TUM-VI -20.9 %), s8 -5.0 %. Runtime +55-75 % (side-file lookups in the smoother loop).'" \
  --decision "'No learned component: with this data (11 flights, 6 rooms) the model does not transfer to an unseen environment at any weighting. The memorisation threat is bounded at about -9 % composite on DEV for this model class and would require the hidden data to be the public sequences; it is not admissible for us (sequence memorisation is excluded by our rules).'" \
  --files "'learned/extract.py, learned/train.py, learned/run_folds.sh, learned/runs_*.log, learned/runs/*/summary.json, notes/make_batch_J.py, notes/batch_J*.json, logs/batch_J*.log'"
